                    "sql": "create or replace table maplemonk.goodtribe_cod_disbursement_fact_items as with tax_report_cod_orders as ( select a.reference_Code, replace(awb_no,\'`\',\'\') as awb, max(b.courier_partner) courier_partner, max(payment_mode) as payment_mode, max(delivered_date) as delivered_date, max(safe_cast(left(ordeR_Date,10) as date)) order_date, max(safe_cast(left(invoice_Date,10) as date)) invoice_Date, sum(ifnull(safE_cast(collectible_amount as float64),0)) collectible_amount, from (select * from goodtribe-wh.maplemonk.easyecom_tax_sales_dedup where MP_Name = \'Shopify\' and payment_mode = \'COD\' ) a left join (select reference_code, awb, max(s.courier) as courier_partner, max(s.delivered_date) as delivered_date from maplemonk.goodtribe_wh_sales_consolidated s group by 1,2 ) b on replace(b.reference_code,\'#\',\'\') = replace(a.reference_code,\'#\',\'\') and replace(a.awb_no,\'`\',\'\') = replace(b.awb,\'`\',\'\') group by 1,2 ), cod_reports as ( select cast(Waybill_Number as string) awb, cast(Order_Number as string) as order_number, parse_date(\'%d%b%Y\',regexp_replace(regexp_extract(_ab_source_file_url, r\'\d{1,2}[a-zA-Z]+\d{4}\'), r\'(\d{1,2})([a-zA-Z]{3})[a-zA-Z]*(\d{4})\', r\'\1\2\3\')) as disbursement_date, cast(Amount_Payable as float64) as order_value, cast(COD_Amount as float64) as cod_amount_paid from `maplemonk.s3_cod_disbursement_delhivery_data` qualify row_number() over (partition by Waybill_Number,Order_Number order by 2 desc, 1 desc) = 1 union all select upper(trim(awb)) as awb, split(cast(`Order Id` as string),\'_\')[offset(0)] as order_number, cast(`Remittance Date` as date) as disbursement_date, cast(`Order Value` as float64) as order_value, cast(`Order Value` as float64) as cod_amount_paid from maplemonk.shiprocket_cod_remittance_report qualify row_number() over (partition by AWB,`Order Id` order by 2 desc, 1 desc) = 1 union all select upper(trim(AWB_No)) as awb, coalesce(Order_id,split(Order_Ref__as_per_Blue_Dart_,\'_\')[offset(0)]) as order_number, cast(parse_date(\'%d-%m-%Y\', neft_date) as date) as disbursement_date, cast(replace(replace(replace(COD_Amount__INR_,\'(\',\'\'),\')\',\'\'),\',\',\'\') as float64) as order_value, cast(replace(replace(replace(COD_Amount__INR_,\'(\',\'\'),\')\',\'\'),\',\',\'\') as float64) as cos_amount_paid from maplemonk.s3_new_consolidated_bluedart_cod_disbursement_data qualify row_number() over (partition by upper(trim(AWB_No)), coalesce(Order_id,split(Order_Ref__as_per_Blue_Dart_,\'_\')[offset(0)]) order by 2 desc, 1 desc) = 1 ) select co.*, c.final_parent_courier, cr.cod_amount_paid, cr.order_value as reported_order_value, cr.disbursement_date, case when cr.cod_amount_paid is not null and round(coalesce(cr.cod_amount_paid, 0), 2) = round(coalesce(co.collectible_amount, 0), 2) then \'Payment Received - Correct\' when cr.cod_amount_paid is not null and round(coalesce(cr.cod_amount_paid, 0), 2) != round(coalesce(co.collectible_amount, 0), 2) then \'Payment Received - Incorrect\' when co.delivered_date is not null and date_diff(current_date(), date(co.delivered_date), day) >= 7 then \'Payment Pending\' when co.delivered_date is not null and date_diff(current_date(), date(co.delivered_date), day) < 7 then \'Delivered (< 7 Days)\' else \'Not Delivered\' end as payment_status, case when cr.cod_amount_paid is not null and round(coalesce(cr.cod_amount_paid, 0), 2) != round(coalesce(co.collectible_amount, 0), 2) then round(coalesce(co.collectible_amount, 0) - coalesce(cr.cod_amount_paid, 0), 2) else 0 end as claim_amount from tax_report_cod_orders co left join cod_reports cr on upper(co.awb) = upper(cr.awb) and replace(co.reference_code,\'#\',\'\') = replace(cr.order_number,\'#\',\'\') left join (select * from maplemonk.gs_courier_mapping qualify row_number() over (partition by upper(trim(courier)) order by 1 desc)=1 ) c on upper(c.courier) = upper(co.courier_partner) ;",
